// Full canvas Run e2e: real control plane (Playwright webServer), real `nurtuo` binary, real SFTP server.
// Gated by NURTUO_CANVAS_RUN_E2E=1 (see playwright.config.ts). Fixtures come from the environment:
// NURTUO_FLOW_RUN_BIN, NURTUO_E2E_SFTP_HOST/_PORT/_USER/_PASSWORD/_FINGERPRINT/_EXPECT and optional _PATH.
// The control-plane login (NURTUO_E2E_CP_EMAIL/_PASSWORD) is generated by the config. Nothing is committed.
import { expect, test, type Page } from "@playwright/test";
import { readFileSync } from "node:fs";

const env = (n: string) => process.env[n] ?? "";
const PASSWORD = env("NURTUO_E2E_SFTP_PASSWORD");
const WRONG_PASSWORD = `wrong-${Math.random().toString(36).slice(2)}-pw`;
const FINGERPRINT = env("NURTUO_E2E_SFTP_FINGERPRINT");
const BAD_FINGERPRINT = "SHA256:AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA";
const PATH = env("NURTUO_E2E_SFTP_PATH") || "/downloads/version.txt";

test.describe.configure({ mode: "serial" });
test.skip(env("NURTUO_CANVAS_RUN_E2E") !== "1", "set NURTUO_CANVAS_RUN_E2E=1 (and the NURTUO_E2E_SFTP_* variables) to run the full canvas Run e2e");

const node = (page: Page, id: string) => page.locator(`.react-flow__node[data-id="${id}"]`);
const status = (page: Page, id: string) => node(page, id).locator(".step-node");
const created: string[] = [];
let bodies: string[] = [];

test.beforeEach(({ page }) => {
  bodies = [];
  page.on("response", async (r) => { if (r.url().includes("/v1/")) bodies.push(await r.text().catch(() => "")); });
});

async function addStep(page: Page, label: string, x: number, y: number) {
  await page.locator(".palette-item", { hasText: new RegExp(`^${label}$`) }).dragTo(page.locator(".react-flow__pane"), { targetPosition: { x, y } });
}
async function connect(page: Page, from: string, to: string) {
  const a = (await node(page, from).locator('.react-flow__handle.source[data-handleid="default"]').boundingBox())!;
  const b = (await node(page, to).locator(".react-flow__handle.target").boundingBox())!;
  await page.mouse.move(a.x + a.width / 2, a.y + a.height / 2);
  await page.mouse.down();
  await page.mouse.move(b.x + b.width / 2, b.y + b.height / 2, { steps: 12 });
  await page.mouse.up();
}

async function login(page: Page) {
  await page.goto("/");
  await expect(page.locator(".react-flow")).toBeVisible();
  await page.getByLabel("Email").fill(env("NURTUO_E2E_CP_EMAIL"));
  await page.getByLabel("Password").fill(env("NURTUO_E2E_CP_PASSWORD"));
  await page.getByRole("button", { name: "Sign in" }).click();
  await expect(page.getByLabel("Workspace")).toBeVisible();
}

async function createConnection(page: Page, id: string, password: string, fingerprint: string) {
  await page.getByRole("button", { name: "Connections" }).click();
  const d = page.getByRole("dialog", { name: "Connections" });
  await d.getByLabel("Connection id").fill(id);
  await d.getByLabel("host", { exact: true }).fill(env("NURTUO_E2E_SFTP_HOST"));
  await d.getByLabel("port").fill(env("NURTUO_E2E_SFTP_PORT"));
  await d.getByLabel("user").fill(env("NURTUO_E2E_SFTP_USER"));
  await d.getByLabel("password").fill(password);
  await d.getByLabel("Host key").fill(fingerprint);
  await d.getByRole("button", { name: "Save connection" }).click();
  await expect(d.locator(`[data-connection="${id}"]`)).toBeVisible();
  created.push(id);
  await d.getByRole("button", { name: "Close" }).click();
}

async function buildFlow(page: Page, connection: string) {
  await addStep(page, "Start", 100, 100);
  await addStep(page, "Connector", 100, 250);
  await addStep(page, "Return Documents", 100, 400);
  await connect(page, "start-1", "connector-1");
  await connect(page, "connector-1", "returndocuments-1");
  await node(page, "connector-1").dblclick();
  const dialog = page.getByRole("dialog");
  const field = (name: string) => dialog.locator("label.field", { hasText: new RegExp(`^${name}`) }).locator("input, textarea").first();
  for (const [name, value] of [["connector", "sftp"], ["operation", "GET"]] as const) {
    await field(name).fill(value);
    await field("label").focus(); // blur commits
  }
  await dialog.getByLabel("connection").selectOption(connection);
  await dialog.getByRole("button", { name: "Close" }).click();
}

async function run(page: Page) {
  await page.getByRole("button", { name: "Run", exact: true }).click();
  const d = page.getByRole("dialog", { name: "Run flow" });
  await d.getByLabel("property value 0").fill(PATH);
  await d.getByRole("button", { name: "Run", exact: true }).click();
  await expect(page.getByTestId("run-status")).toBeVisible({ timeout: 60_000 });
}

test.afterAll(async ({ browser }) => {
  // Cleanup: delete what the tests created (connections through the UI endpoint, secrets through the API).
  const page = await browser.newPage();
  try {
    await login(page);
    await page.evaluate(async (ids) => {
      const me = await (await fetch("/v1/auth/me")).json();
      const ws = me.workspaces[0].id, h = { "x-nurtuo-csrf": me.csrfToken };
      for (const id of ids) {
        await fetch(`/v1/workspaces/${ws}/connections/${id}`, { method: "DELETE", headers: h });
        await fetch(`/v1/workspaces/${ws}/secrets/${id}-password`, { method: "DELETE", headers: h });
      }
    }, created);
  } finally { await page.close(); }
});

test("run SFTP GET: succeeded, text preview, three green nodes; no password in the export or any response", async ({ page }) => {
  await login(page);
  await createConnection(page, "e2e-sftp", PASSWORD, FINGERPRINT);
  await buildFlow(page, "e2e-sftp");
  await run(page);
  await expect(page.getByTestId("run-status")).toHaveText("succeeded");
  await expect(page.getByTestId("doc-preview")).toHaveText(env("NURTUO_E2E_SFTP_EXPECT").trimEnd());
  for (const id of ["start-1", "connector-1", "returndocuments-1"]) await expect(status(page, id)).toHaveAttribute("data-run-status", "ok");

  const [dl] = await Promise.all([page.waitForEvent("download"), page.getByRole("button", { name: "Save flow" }).click()]);
  const exported = readFileSync((await dl.path())!, "utf8");
  expect(exported).not.toContain(PASSWORD);
  expect(exported).toContain("e2e-sftp");
  expect(bodies.length).toBeGreaterThan(0);
  for (const b of bodies) expect(b).not.toContain(PASSWORD);
  expect(await page.locator("body").innerText()).not.toContain(PASSWORD);
});

test("wrong fingerprint: connector error with host key mismatch", async ({ page }) => {
  await login(page);
  await createConnection(page, "e2e-sftp-badfp", PASSWORD, BAD_FINGERPRINT);
  await buildFlow(page, "e2e-sftp-badfp");
  await run(page);
  await expect(page.getByTestId("run-status")).toHaveText("failed");
  await expect(status(page, "connector-1")).toHaveAttribute("data-run-status", "error");
  await expect(page.getByText(/host key mismatch/).first()).toBeVisible();
  for (const b of bodies) expect(b).not.toContain(PASSWORD);
});

test("wrong password: connector error; neither password appears on the page or in responses", async ({ page }) => {
  await login(page);
  await createConnection(page, "e2e-sftp-badpw", WRONG_PASSWORD, FINGERPRINT);
  await buildFlow(page, "e2e-sftp-badpw");
  await run(page);
  await expect(page.getByTestId("run-status")).toHaveText("failed");
  await expect(status(page, "connector-1")).toHaveAttribute("data-run-status", "error");
  const text = await page.locator("body").innerText();
  expect(text).not.toContain(PASSWORD);
  expect(text).not.toContain(WRONG_PASSWORD);
  for (const b of bodies) { expect(b).not.toContain(PASSWORD); expect(b).not.toContain(WRONG_PASSWORD); }
});
